+/**
+ * Seeds the history with a selection "A" followed by a clipboard "B", so that the newest entry
+ * is not the one the selection holds. A clipboard update that did not come from a text
+ * selection, such as copying a file in Dolphin, is what produces this in practice.
+ */
+void HistoryModelTest::seedSelectionAndClipboard()
+{
+    std::shared_ptr<HistoryModel> history = HistoryModel::self();
+    history->clear();
+    history->setMaxSize(10);
+    writeSetting(QStringLiteral("SaveSelection"), true);
+
+    QMimeData selection;
+    selection.setText(QStringLiteral("A"));
+    QVERIFY(history->insert(&selection, 0, true));
+    // insert() has to record the entry as the current selection, not just as the clipboard
+    QCOMPARE(history->m_systemSelectionUuid, uuidOf(QStringLiteral("A")));
+
+    QMimeData clipboard;
+    clipboard.setText(QStringLiteral("B"));
+    QVERIFY(history->insert(&clipboard, 0, false));
+
+    QCOMPARE(history->rowCount(), 2);
+}
