+
+void HistoryModel::updateSystemUuid(QClipboard::Mode mode, const QString &uuid)
+{
+    QString &tracked = mode == QClipboard::Selection ? m_systemSelectionUuid : m_systemClipboardUuid;
+    if (tracked == uuid) {
+        return;
+    }
+    const QString previous = std::exchange(tracked, uuid);
+
+    const int role = mode == QClipboard::Selection ? TopSelectionRole : TopClipboardRole;
+    for (const QString &changed : {previous, uuid}) {
+        if (const int row = indexOf(changed); row >= 0) {
+            Q_EMIT dataChanged(index(row), index(row), {role});
+        }
+    }
+}
+
+void HistoryModel::updateSystemUuids(const QString &uuid, bool selectionMode)
+{
+    // With "Keep the selection and clipboard the same" the entry ends up in both buffers.
+    if (selectionMode || m_bSynchronize) {
+        updateSystemUuid(QClipboard::Selection, uuid);
+    }
+    if (!selectionMode || m_bSynchronize) {
+        updateSystemUuid(QClipboard::Clipboard, uuid);
+    }
+}
