+std::unique_ptr<QMimeData> Utils::cloneMimeData(const QMimeData *data)
+{
+    auto clone = std::make_unique<QMimeData>();
+    if (data->hasImage()) {
+        clone->setImageData(data->imageData());
+    }
+    if (data->hasText()) {
+        clone->setText(data->text());
+    }
+    for (const QStringList formats = data->formats(); const QString &format : formats) {
+        if (format.startsWith(s_plainTextPrefix) || format.startsWith(u"image/") || format == u"application/x-qt-image") {
+            continue; // Already copied above
+        }
+        clone->setData(format, data->data(format));
+    }
+    return clone;
+}
